/**
 * backfill-breakdown-elaboration.js — write, per multi-character zh word, the short note
 * that sits under its character breakdown and explains how the characters get to the
 * meaning — or decide that no note is needed.
 *
 * WHY
 *   `dictionaryentries_zh.breakdown` glosses each component character of a word
 *   (generated by backfill-dictionary-breakdown.js, sense-corrected by
 *   backfill-breakdown-senses.js). The glosses say WHAT the word is made of; the note
 *   says WHY those parts add up. The preferred note explains the LITERAL TRANSLATION —
 *   the characters read in order as a blunt English phrase, then what that phrase
 *   pictures and how the picture becomes the meaning, naming the symbol when a concrete
 *   thing stands for something abstract:
 *     住手  “Stop hand”: stop moving your hand. The hand stands for whatever you're doing.
 *     火车  “Fire vehicle”: named in the steam age when trains ran on burning coal.
 *   The model labels each answer with one of three kinds (NOT stored — used only to
 *   validate the note's shape):
 *     image   — literal translation + the picture/symbol bridge (the common case)
 *     origin  — literal translation + the story/allusion it only makes sense through
 *               (矛盾 “Spear shield”, 吃醋 “Eat vinegar”)
 *     sound   — a transliteration; NO literal translation, because one would mislead
 *               (沙发 → "Chosen for sound, to spell out “sofa”. …")
 *   and NULL when the literal translation simply IS the definition (学生, 树林, 会议),
 *   for function words (然而), suffix-only compounds, and disputed origins (东西, 马虎).
 *   Mild images count when the picture is really in the word (火车, 开心, 东正教's calque
 *   of "orthodox"); an invented simile ("like a dot on a map") does not.
 *
 *   v1 (until 2026-11-07) asked the opposite question — "is this breakdown OPAQUE?" —
 *   and so dropped exactly the 住手 / 动手 / 放心 family this version is built for, while
 *   drifting into "Here X means Y" sense corrections its own prompt forbade (11,108 of
 *   27,595 dev rows ended up with a note, against a ~30% design).
 *
 * WHAT IT WRITES  (migration 133 — authored as 130, renumbered in merge ef7b964)
 *   dictionaryentries_zh."breakdownElaboration" — the note (one or two short sentences),
 *   or NULL. The literal translation lives INSIDE the note, as its quoted opening; there
 *   is deliberately no separate column for it (user decision 2026-11-07).
 *
 *   ⚠️ NULL IS A REAL ANSWER, not "not yet processed". "No note" is a common verdict, so
 *   the column cannot double as a done-gate. Evaluated-ness lives in the per-entry
 *   `enrichmentLog` stamp (migration 68) under this script's id, which is written for
 *   EVERY decided row — including the NULL ones. That stamp, not the column, is what the
 *   default WHERE gate reads.
 *
 * LENGTH CAP
 *   100 characters for a 2-character word, 150 for 3+ (idioms and allusions need room
 *   for the story). A CAP, not a target: the prompt says so explicitly, because a
 *   stated length becomes the length. Over-cap answers are retried ONCE with the
 *   overage quoted back and a tighter limit (RETRY_FRACTION of the cap — a model told
 *   "at most 100" reliably lands at 101–104); a second over-cap answer is left
 *   unwritten and unstamped (⚠ review line) so a later run retries it rather than
 *   silently truncating prose mid-thought.
 *
 * FLAGS
 *   --words=住手,马虎   scope to specific headwords
 *   --all               include non-discoverable entries
 *   --force             re-decide rows already stamped (clears a stale note when the
 *                       verdict flips to "no note")
 *   --stale             no-op: the default gate already includes rows stamped below the
 *                       current SCRIPT_VERSION (so the planner's bare --words= works)
 *   --limit=N           cap the batch
 *   --spot-check        5 random entries (or the --words set), NO writes, verbose
 *
 * Depends on: backfill-dictionary-breakdown.js (breakdown must exist) and, for a
 * trustworthy literal translation, backfill-breakdown-senses.js (glosses should be the
 * in-context senses, not the global lead glosses — the prompt still tells the model to
 * silently use the right sense when a shown gloss is plainly wrong).
 * Referenced by docs/BREAKDOWN_FEATURE_IMPLEMENTATION.md § 5c, and the manifest row in
 * shared/lib/requiredScripts.js (its `version` must equal SCRIPT_VERSION —
 * check-manifest-sync.js).
 */
import dotenv from 'dotenv';
import { fileURLToPath } from 'url';
import path from 'path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.resolve(__dirname, '../../../.env') });

import Anthropic from '@anthropic-ai/sdk';
import db from '../../../db.js';
import { initRunLog, cachedSystem } from '../run-log.js';

// v2 (2026-11-07): literal-translation rubric replaces v1's "is it opaque?" judge.
const SCRIPT_VERSION = 2; // bump when this script's logic/prompt changes
const SCRIPT_ID = 'chinese/backfill-breakdown-elaboration';
const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
const { stampEntries, staleClause } = initRunLog({ script: SCRIPT_ID, version: SCRIPT_VERSION, anthropic });

const MODEL = 'claude-sonnet-4-6';

// Hard caps on the note, in characters the reader sees (see LENGTH CAP above).
const CAP_TWO_CHAR = 100;
const CAP_LONGER = 150;

// The over-cap retry is told this fraction of the real cap, so a near-miss on the
// retry still clears the actual ceiling.
const RETRY_FRACTION = 0.8;

// The three note kinds the model may return (plus null = no note). Not stored.
const NOTE_KINDS = new Set(['image', 'origin', 'sound']);

// Stable marker so the mark-discoverable skill agent can grep review flags off stdout
// (same convention as the clusterer and the breakdown sense tagger).
const REVIEW_MARKER = '⚠ BREAKDOWN ELABORATION REVIEW';

// ── args ────────────────────────────────────────────────────────────────────
const args = process.argv.slice(2);
const hasFlag = (f) => args.includes(f);
const getArg = (name) => {
  const a = args.find((x) => x.startsWith(`${name}=`));
  return a ? a.slice(name.length + 1) : null;
};
const ALL = hasFlag('--all');
const FORCE = hasFlag('--force');
// --stale is accepted but is a no-op (see the done-gate in run()).
const SPOT_CHECK = hasFlag('--spot-check');
const LIMIT = getArg('--limit') ? parseInt(getArg('--limit'), 10) : null;
const wordsArg = getArg('--words');
const targetWords = wordsArg ? wordsArg.split(',').map((s) => s.trim()).filter(Boolean) : null;

// ── helpers ─────────────────────────────────────────────────────────────────
/** Codepoint-safe length — the cap is counted in characters the reader sees. */
const charLen = (s) => Array.from(String(s ?? '')).length;

/** Per-word note cap: 100 for a 2-char word, 150 for 3+ (idioms, allusions). */
const capFor = (word) => (charLen(word) >= 3 ? CAP_LONGER : CAP_TWO_CHAR);

function parseJsonObject(text) {
  const stripped = String(text).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  const match = stripped.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try {
    const parsed = JSON.parse(match[0]);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

/**
 * Parse the model's {kind, explanation} verdict. Tries strict JSON first; on failure
 * falls back to a tolerant extraction, because the note itself is full of quotation
 * marks and models (Sonnet 4.6 in particular, observed 2026-11-07) normalize the
 * prompt's curly “…” to straight "…" — which, unescaped inside a JSON string, makes the
 * whole object invalid: {"explanation": ""Stop hand": stop moving …"}.
 * The fallback takes `kind` by regex and `explanation` as everything between its
 * opening quote and the LAST quote before the closing brace, so inner quotes survive.
 * @returns {{kind: string|null, explanation?: string}|null}
 */
function parseVerdict(text) {
  const strict = parseJsonObject(text);
  if (strict && 'kind' in strict) return strict;

  const body = String(text).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  const kindMatch = body.match(/"kind"\s*:\s*(null|"([a-z]+)")/);
  if (!kindMatch) return null;
  const kind = kindMatch[1] === 'null' ? null : kindMatch[2];
  if (kind === null) return { kind: null };
  const explMatch = body.match(/"explanation"\s*:\s*"([\s\S]*)"\s*\}\s*$/);
  return explMatch ? { kind, explanation: explMatch[1] } : { kind };
}

/**
 * Normalize quotation marks in a note to curly quotes, so every stored note looks the
 * same whichever model (or oracle answerer) wrote it: straight "…" pairs → “…”, and
 * JSON-escaped \" (if strict parsing kept any) likewise. Apostrophes are left alone.
 */
function normalizeQuotes(note) {
  let open = true;
  return note.replace(/\\?"/g, () => {
    const q = open ? '“' : '”';
    open = !open;
    return q;
  });
}

/**
 * Render the breakdown for the prompt in WORD ORDER. The `breakdown` jsonb is keyed by
 * character, so its own key order is jsonb's (length, then bytes) — not the order the
 * characters appear in. Walking word1 restores reading order, which the literal
 * translation depends on ("stop hand", not "hand stop").
 * Repeated characters (e.g. 天天) collapse to one key, so they are simply re-read.
 */
function breakdownLines(word, breakdown) {
  return Array.from(word).map((char, i) => {
    const v = breakdown?.[char];
    const def = (v && typeof v === 'object' ? v.definition : typeof v === 'string' ? v : null) || '(no gloss)';
    const sense = v && typeof v === 'object' && typeof v.sense === 'string' ? ` [sense: ${v.sense}]` : '';
    return `  ${i + 1}. ${char} = ${def}${sense}`;
  }).join('\n');
}

// ── model call ──────────────────────────────────────────────────────────────
// Tuned 2026-11-07 against a 34-word curated set (住手, 动手, 放心, 东西, 沙发, 会议 …)
// and a 38-word random discoverable sample. {{CAP}} is substituted per word.
const SYSTEM = `You write the short note under a Chinese word's character breakdown, for an English-speaking learner. The learner already sees the word, its English definition, and a gloss for each character. Your note answers one question: how do these characters get to this meaning?

The most useful note is usually an explanation of the LITERAL TRANSLATION. Read the characters, in order, as a blunt English phrase, open the note with it, and then explain it: what that phrase pictures and how the picture becomes the meaning. Name the symbol when a concrete thing stands for something abstract: a hand for deliberate action, the mouth for speech, the heart for the mind or feelings, the eyes for attention or envy.

Examples of kind "image":
  住手 (to stop). 住 = to stop, 手 = hand.
  {"kind": "image", "explanation": "“Stop hand”: stop moving your hand. The hand stands for whatever you're doing."}

  电脑 (computer). 电 = electric, 脑 = brain.
  {"kind": "image", "explanation": "“Electric brain”: the machine pictured as a brain that runs on electricity."}

  火车 (train). 火 = fire, 车 = vehicle.
  {"kind": "image", "explanation": "“Fire vehicle”: named in the steam age when trains ran on burning coal."}

Mild images count. If the literal translation adds a real picture, connotation or bit of history beyond the bare definition, write the note: 火车's steam-age coal fire, 开心's heart opening up, a calque like 东正教 “east correct religion” translating Greek “orthodox”.

But the picture must come FROM THE WORD: a real sense of a character, real history, a real calque or allusion. If the only way to make the note interesting is a simile you made up (“like a dot on a map”, “as if standing it upright”), there is no picture: answer null.

Two other kinds of note exist:

- kind "origin": the characters only make sense through a story, allusion, or a fossilized older phrase. Open with the literal translation, then tell the story in one breath.
  推敲 (to deliberate over wording). 推 = push, 敲 = knock.
  {"kind": "origin", "explanation": "“Push knock”: a Tang poet agonized over whether his monk should push or knock on a gate."}

- kind "sound": the characters were picked for their sound to spell out a foreign word, so a literal translation would only mislead. Do NOT give one.
  咖啡 (coffee).
  {"kind": "sound", "explanation": "Chosen for sound, to spell out “coffee”. The characters' meanings play no part."}

Write NO note (kind null) when the literal translation simply IS the definition and explaining it adds nothing: 学生 “study person” = student, 树林 “tree forest” = woods, 共用 “together use” = share, 会议 “meet discuss” = meeting, 开口 “open mouth” = start to talk, 点头 “nod head” = nod. Also null when:
- One character is a grammatical suffix or bound form (子, 儿, 化, 性, 们 …) and the rest is plain.
- The word is a function word: a conjunction, adverb of logic, or particle (然而, 因为, 所以, 而且 …). Its parts are grammar, not pictures.
- The literal translation is just a more wordy way of saying the definition: 学堂 “learning hall” = school, 地点 “ground point” = place, 雷雨 “thunder rain” = thunderstorm.
- You cannot explain the link honestly because the origin is unknown or disputed. Never invent folk etymology, and never add decorative imagery that isn't really in the word.

Rules:
- Open "image" and "origin" notes with the translation in curly quotes, first letter capitalized, then a colon: “Stop hand”: … Do not write the word “Literally”; the quotes alone mark it. The translation is the characters in order as a short, blunt English phrase, using the sense each character carries IN THIS WORD. If a shown gloss is plainly the wrong sense for this word, use the right one silently; do not comment on the correction.
- Then explain it, concisely, in plain English addressed to the learner: the picture and the bridge to the meaning. Don't restate the definition on its own and don't re-list the glosses. No Chinese characters unless naming one is unavoidable.
- HARD CAP: the whole note, including the opening translation, must be {{CAP}} characters or fewer. This is a ceiling, not a target: say it in as few words as it takes and stop.
- If the word has several senses, explain the core picture only.

Inside the explanation, use only curly quotes “ ” for quoted words, never straight double quotes ("), which would break the JSON.

Respond with ONLY a JSON object, one of:
{"kind": "image", "explanation": "..."}
{"kind": "origin", "explanation": "..."}
{"kind": "sound", "explanation": "..."}
{"kind": null}`;

/**
 * The shape rules a note must satisfy beyond the length cap. Returns a reason string
 * when the note is malformed, else null. image/origin notes must OPEN with the quoted
 * literal translation (that is the whole point of the rubric); sound notes must not
 * carry one. The model was told not to write "Literally" — the quotes alone mark it.
 */
function shapeProblem(kind, note) {
  if (/^literally\b/i.test(note)) return 'opens with "Literally" (the quotes alone should mark the translation)';
  if ((kind === 'image' || kind === 'origin') && !note.startsWith('“')) return `${kind} note does not open with the quoted literal translation`;
  return null;
}

/**
 * Ask the model for one word's note.
 * @returns {{kind: string|null, note: string|null}|null} null = unusable response
 */
async function callJudge(word, entry, retryNote, capOverride) {
  const cap = capOverride ?? capFor(word);
  const defs = Array.isArray(entry.definitions) ? entry.definitions.filter((d) => typeof d === 'string') : [];

  const userText = [
    `Word: ${word}`,
    entry.pronunciation ? `Pronunciation: ${entry.pronunciation}` : null,
    `Definition: ${defs.length ? defs.join('; ') : '(none)'}`,
    '',
    'Character breakdown as the learner sees it:',
    breakdownLines(word, entry.breakdown),
    '',
    `Note length: hard cap ${cap} characters (a cap, not a target).`,
    retryNote ?? null,
  ].filter((l) => l !== null).join('\n');

  try {
    const response = await anthropic.messages.create({
      model: MODEL,
      max_tokens: 600, // ceiling only; generous so a long idiom note can't be truncated mid-JSON
      temperature: 0.2,
      // NOTE: the system text varies with the cap (2-char vs 3+), so the prompt cache
      // splits into two prefixes. 2-char words dominate, so most calls share one.
      system: cachedSystem(SYSTEM.replaceAll('{{CAP}}', String(cap))),
      messages: [{ role: 'user', content: userText }],
    });
    // First TEXT block, not content[0]: a thinking-enabled model puts a thinking block
    // first, so content[0].text would be undefined there.
    const text = response.content.find((b) => b.type === 'text')?.text ?? '';
    const parsed = parseVerdict(text);
    // Every unusable-response path flags itself: an undecided row is skipped AND left
    // unstamped, so a silent one would look identical to a "no note" one in the
    // summary while quietly costing a call on every future run.
    if (!parsed || !('kind' in parsed) || (parsed.kind !== null && !NOTE_KINDS.has(parsed.kind))) {
      // Quote the raw text (truncated) so a systematic format failure is diagnosable
      // from stdout alone, without re-running.
      const raw = text.replace(/\s+/g, ' ').slice(0, 200);
      console.log(`${REVIEW_MARKER} ${word}: unparseable verdict — not stamped, will retry. Raw: ${raw}`);
      return null;
    }
    if (parsed.kind === null) return { kind: null, note: null };

    const note = typeof parsed.explanation === 'string' ? normalizeQuotes(parsed.explanation.trim()) : '';
    if (!note) {
      // A kind with nothing to say is not a usable verdict.
      console.log(`${REVIEW_MARKER} ${word}: kind "${parsed.kind}" but no explanation text`);
      return null;
    }
    const problem = shapeProblem(parsed.kind, note);
    if (problem) {
      console.log(`${REVIEW_MARKER} ${word}: ${problem} — not stamped, will retry: ${note}`);
      return null;
    }
    return { kind: parsed.kind, note };
  } catch (e) {
    console.log(`${REVIEW_MARKER} ${word}: judge call failed (${e.message})`);
    return null;
  }
}

/**
 * Full per-word decision including the one over-cap retry.
 * @returns {{elaboration: string|null, kind: string|null}|null} null = undecided (caller
 *          must NOT stamp, so a later run retries the row rather than freezing a bad/absent
 *          answer in).
 */
async function decide(word, entry) {
  const cap = capFor(word);

  let verdict = await callJudge(word, entry, null);
  if (!verdict) return null;
  if (!verdict.note) return { elaboration: null, kind: null };

  if (charLen(verdict.note) > cap) {
    // Retry once with the overage quoted back. Truncating prose would cut a sentence
    // mid-thought, so the model gets one chance to say the same thing shorter — told a
    // TIGHTER limit than the real one so a near-miss still clears the actual cap.
    const over = charLen(verdict.note);
    const retryCap = Math.round(cap * RETRY_FRACTION);
    verdict = await callJudge(
      word,
      entry,
      `Your previous note was ${over} characters — over the cap. Rewrite it in at most ${retryCap} characters: keep the quoted translation and the bridge to the meaning, cut everything else. If it cannot be said that briefly, answer {"kind": null}.`,
      retryCap
    );
    if (!verdict) return null;
    if (!verdict.note) return { elaboration: null, kind: null };
    if (charLen(verdict.note) > cap) {
      console.log(`${REVIEW_MARKER} ${word}: still ${charLen(verdict.note)}/${cap} chars after retry — left unwritten`);
      return null;
    }
  }

  return { elaboration: verdict.note, kind: verdict.kind };
}

// ── main ────────────────────────────────────────────────────────────────────
async function run() {
  console.log('Starting breakdown-elaboration backfill...\n');
  if (targetWords?.length) console.log(`🎯 Scoped to: ${targetWords.join(', ')}`);
  if (SPOT_CHECK) console.log('🔎 SPOT-CHECK mode — NO writes\n');

  const client = await db.getClient();
  try {
    const conds = [
      `language = 'zh'`,
      `char_length(word1) > 1`,
      `breakdown IS NOT NULL`,
      `breakdown <> 'null'::jsonb`,
    ];
    const params = [];
    // A --words run targets exactly those rows, INCLUDING not-yet-discoverable ones —
    // that is how the lazy-enrichment worker and /oracle-backfill drive this step for a
    // word being brought up to discoverable. Untargeted full-table runs keep the gate.
    // (Same convention as backfill-classifier.js; --all forces the gate off outright.)
    if (!ALL && !targetWords?.length) conds.push('discoverable = TRUE');

    // Done-gate. NOT `breakdownElaboration IS NULL` — NULL is a legitimate verdict, so
    // gating on it would re-judge (and re-pay for) every no-note word forever.
    // Default: rows never stamped OR stamped below the current SCRIPT_VERSION — the same
    // definition of "pending" oracle-plan.js uses. That matters because the planner hands
    // this script a bare `--words=` list (it never adds --stale), so a gate that skipped
    // older-version stamps would leave every v1 row re-planned and skipped forever after
    // a version bump. (Same choice as backfill-max-char-stroke-count.js.) --stale is
    // therefore a no-op alias kept for muscle memory; --force: no gate at all.
    if (!FORCE) conds.push(staleClause());
    if (targetWords?.length) { params.push(targetWords); conds.push(`word1 = ANY($${params.length})`); }

    // Spot-check samples RANDOMLY (quality across the corpus, not just the lowest ids);
    // the real run keeps deterministic id order for resumability.
    let sql = `SELECT id, word1, pronunciation, definitions, breakdown, "breakdownElaboration"
                 FROM dictionaryentries_zh
                WHERE ${conds.join(' AND ')}
                ORDER BY ${SPOT_CHECK ? 'RANDOM()' : 'id'}`;
    if (SPOT_CHECK) sql += ` LIMIT ${LIMIT ?? 5}`;
    else if (LIMIT) sql += ` LIMIT ${LIMIT}`;

    const { rows: entries } = await client.query(sql, params);
    console.log(`Found ${entries.length} entries to judge\n`);
    if (entries.length === 0) { console.log('No entries to process.'); return; }

    let processed = 0, elaborated = 0, noNote = 0, undecided = 0, failed = 0;
    for (const entry of entries) {
      processed++;
      try {
        const decision = await decide(entry.word1, entry);
        if (!decision) { undecided++; continue; } // not stamped — a later run retries

        if (SPOT_CHECK) {
          if (decision.elaboration) {
            console.log(`✎ ${entry.word1} [${decision.kind}] (${charLen(decision.elaboration)}/${capFor(entry.word1)} chars): ${decision.elaboration}`);
          } else {
            console.log(`— ${entry.word1}: no note`);
          }
        } else {
          // Always write the column — a re-run whose verdict flipped to "no note" must
          // CLEAR the stale note, not leave it stranded. (This is also how a --stale v2
          // run clears v1's sense-correction notes.)
          await client.query(
            `UPDATE dictionaryentries_zh SET "breakdownElaboration" = $1 WHERE id = $2`,
            [decision.elaboration, entry.id]
          );
          await stampEntries(client, 'dictionaryentries_zh', entry.id);
        }
        if (decision.elaboration) elaborated++; else noNote++;

        if (!SPOT_CHECK && processed % 50 === 0) {
          console.log(`Progress: ${processed}/${entries.length} (${Math.round((processed / entries.length) * 100)}%)`);
        }
      } catch (e) {
        failed++;
        console.error(`Failed ID ${entry.id} "${entry.word1}": ${e.message}`);
      }
    }

    console.log('\n' + '='.repeat(60));
    console.log('BREAKDOWN ELABORATION SUMMARY');
    console.log('='.repeat(60));
    console.log(`Processed:        ${processed}`);
    console.log(`Elaborated:       ${elaborated}${SPOT_CHECK ? ' (not written — spot-check)' : ''}`);
    console.log(`No note:          ${noNote} (written as NULL)`);
    console.log(`Undecided:        ${undecided} (unusable/malformed/over-cap response — not stamped, will retry)`);
    console.log(`Failed:           ${failed}`);
    console.log('='.repeat(60));
  } catch (e) {
    console.error('Fatal error during backfill:', e);
    throw e;
  } finally {
    client.release();
    await db.pool.end();
  }
}

run().catch((e) => { console.error('Fatal error:', e); process.exit(1); });
